// Adapted from Zard UI 1.1.1 (MIT) — https://github.com/zard-ui/zardui
import { Dialog, DialogRef } from "@angular/cdk/dialog";
import { NgTemplateOutlet } from "@angular/common";
import {
  afterNextRender,
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChild,
  DestroyRef,
  Directive,
  effect,
  ElementRef,
  inject,
  input,
  model,
  TemplateRef,
  untracked,
  viewChild,
  ViewContainerRef,
} from "@angular/core";
import { NgIcon } from "@ng-icons/core";
import { lucideX } from "@ng-icons/lucide";
import {
  KO_DIALOG_BACKDROP_CLASS,
  KO_DIALOG_PANEL_CLASS,
  KO_DIALOG_SIZE,
} from "@/ui/primitives/dialog.service";
import { animateExit, type KoExitController } from "@/ui/primitives/dialog-exit";
import { linkToPanel } from "@/ui/primitives/dialog-panel";
import { cn } from "@/ui/utils";

let nextId = 0;

/** Marks the content of a `ko-dialog`: `<ng-template koDialogContent>`. */
@Directive({ selector: "ng-template[koDialogContent]" })
export class KoDialogContent {
  readonly template = inject<TemplateRef<unknown>>(TemplateRef);
}

/** Closes the surrounding dialog: a `ko-dialog`, or one opened by `KoDialogService`. */
@Directive({
  selector: "button[koDialogClose]",
  host: { "[attr.type]": "'button'", "(click)": "close()" },
})
export class KoDialogClose {
  private readonly dialog = inject(KoDialog, { optional: true });
  private readonly ref = inject(DialogRef, { optional: true });

  protected close(): void {
    if (this.dialog) this.dialog.requestClose();
    else this.ref?.close();
  }
}

/** Opens a `ko-dialog` on click. */
@Directive({
  selector: "[koDialogTrigger]",
  host: {
    "aria-haspopup": "dialog",
    "[attr.aria-expanded]": "dialog().open()",
    "(click)": "dialog().open.set(true)",
  },
})
export class KoDialogTrigger {
  readonly dialog = input.required<KoDialog>({ alias: "koDialogTrigger" });
}

/**
 * A modal dialog. `[(open)]` works both ways: Escape, a backdrop click and `koDialogClose` write
 * `false` back once the exit animation has played. The content goes in `<ng-template koDialogContent>`.
 */
@Component({
  selector: "ko-dialog",
  imports: [NgTemplateOutlet, NgIcon, KoDialogClose],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: "contents" },
  template: `
    <ng-template #shell>
      <div [class]="shellClasses()">
        <ng-container [ngTemplateOutlet]="content()?.template ?? null" />
        <button
          koDialogClose
          class="absolute right-3 top-3 rounded-sm p-2 text-muted-foreground hover:bg-secondary hover:text-foreground"
        >
          <ng-icon aria-hidden="true" size="1rem" [svg]="close" />
          <span class="sr-only">Close</span>
        </button>
      </div>
    </ng-template>
  `,
})
export class KoDialog {
  readonly open = model(false);
  /** The panel's max width, set through the overlay config (the CDK pane ignores `max-w-*`). */
  readonly maxWidth = input<string>(KO_DIALOG_SIZE.maxWidth);
  /** Classes merged onto the padded wrapper around the content, such as `p-0 gap-0`. */
  readonly contentClass = input<string>("");
  /**
   * Ignore Escape and backdrop clicks while true (for example during a pending save).
   * `koDialogClose` and `open.set(false)` still close. Changes apply to an open dialog.
   */
  readonly disableClose = input(false, { transform: booleanAttribute });

  protected readonly close = lucideX;
  protected readonly content = contentChild(KoDialogContent);
  protected readonly shellClasses = computed(() =>
    cn("relative grid gap-4 p-5", this.contentClass()),
  );
  private readonly shell = viewChild.required<TemplateRef<unknown>>("shell");
  private readonly dialog = inject(Dialog);
  private readonly viewContainerRef = inject(ViewContainerRef);
  private ref?: DialogRef<unknown, unknown>;
  private exit?: KoExitController;

  constructor() {
    effect(() => {
      const open = this.open();
      untracked(() => (open ? this.show() : this.ref?.close()));
    });
    // The CDK reads `disableClose` when a key or backdrop click arrives, so setting it on the ref
    // is enough to make a change apply to a dialog that is already open.
    effect(() => {
      const disableClose = this.disableClose();
      if (this.ref) this.ref.disableClose = disableClose;
    });
    inject(DestroyRef).onDestroy(() => (this.exit ? this.exit.closeNow() : this.ref?.close()));
  }

  /**
   * Closes through the exit animation; `open` flips to false once the dialog is really gone.
   * Used by `koDialogClose`.
   */
  requestClose(): void {
    if (this.ref) this.ref.close();
    else this.open.set(false);
  }

  private show(): void {
    if (this.ref) {
      // Reopened during the exit animation: cancel the pending close and keep this dialog.
      this.exit?.cancel();
      return;
    }
    const ref = this.dialog.open(this.shell(), {
      role: "dialog",
      ariaModal: true,
      ...KO_DIALOG_SIZE,
      maxWidth: this.maxWidth(),
      disableClose: this.disableClose(),
      viewContainerRef: this.viewContainerRef,
      panelClass: KO_DIALOG_PANEL_CLASS,
      backdropClass: KO_DIALOG_BACKDROP_CLASS,
    });
    this.ref = ref;
    this.exit = animateExit(ref, "dialog");
    ref.closed.subscribe(() => {
      if (this.ref === ref) this.ref = this.exit = undefined;
      this.open.set(false);
    });
  }
}

@Component({
  selector: "ko-dialog-header",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { "[class]": "classes()" },
  template: `<ng-content />`,
})
export class KoDialogHeader {
  readonly class = input<string>("");
  protected readonly classes = computed(() => cn("flex flex-col gap-1.5 pr-8", this.class()));
}

@Component({
  selector: "ko-dialog-footer",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { "[class]": "classes()" },
  template: `<ng-content />`,
})
export class KoDialogFooter {
  readonly class = input<string>("");
  protected readonly classes = computed(() =>
    cn("flex flex-col-reverse gap-2 sm:flex-row sm:justify-end", this.class()),
  );
}

@Component({
  selector: "ko-dialog-title",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { "[class]": "classes()", "[attr.id]": "id" },
  template: `<ng-content />`,
})
export class KoDialogTitle {
  readonly class = input<string>("");
  protected readonly id = `ko-dialog-title-${nextId++}`;
  protected readonly classes = computed(() =>
    cn("block text-base font-medium tracking-tight", this.class()),
  );

  constructor() {
    const host = inject<ElementRef<HTMLElement>>(ElementRef).nativeElement;
    afterNextRender(() => linkToPanel(host, "aria-labelledby"));
  }
}

@Component({
  selector: "ko-dialog-description",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { "[class]": "classes()", "[attr.id]": "id" },
  template: `<ng-content />`,
})
export class KoDialogDescription {
  readonly class = input<string>("");
  protected readonly id = `ko-dialog-description-${nextId++}`;
  protected readonly classes = computed(() =>
    cn("block text-sm text-muted-foreground", this.class()),
  );

  constructor() {
    const host = inject<ElementRef<HTMLElement>>(ElementRef).nativeElement;
    afterNextRender(() => linkToPanel(host, "aria-describedby"));
  }
}

// Adapted from Zard UI 1.1.1 (MIT) — https://github.com/zard-ui/zardui
import { Dialog, type DialogRef } from "@angular/cdk/dialog";
import { inject, Injectable, type Type } from "@angular/core";
import { animateExit } from "@/ui/primitives/dialog-exit";

/** Panel classes from the React `DialogContent`; padding is added where the panel has no wrapper. */
export const KO_DIALOG_PANEL_CLASS = [
  "rounded-xl",
  "bg-popover",
  "shadow-[var(--shadow-elevated)]",
  "duration-200",
  "animate-in",
  "fade-in-0",
  "zoom-in-95",
];

/**
 * Size goes through the overlay config (inline styles): the CDK injects an unlayered
 * `.cdk-overlay-pane { max-width: 100% }` that beats Tailwind utilities, so `max-w-lg` cannot work.
 * 32rem is `--container-lg`.
 */
export const KO_DIALOG_SIZE = { width: "calc(100% - 2rem)", maxWidth: "32rem" } as const;

/** Backdrop classes from the React `DialogOverlay`. */
export const KO_DIALOG_BACKDROP_CLASS = ["bg-background/70", "animate-in", "fade-in-0"];

export interface KoDialogConfig<D = unknown> {
  data?: D;
  ariaLabel?: string;
  /** Ignore Escape and backdrop clicks; `ref.close()` still closes. Also settable on the ref. */
  disableClose?: boolean;
}

/**
 * Opens a component in the dialog overlay: focus trap, Escape, backdrop click and focus return
 * come from the CDK, and `ref.close()` plays the exit animation before `closed` emits. Put
 * `ko-dialog-title` in the component, or pass `ariaLabel`.
 */
@Injectable({ providedIn: "root" })
export class KoDialogService {
  private readonly dialog = inject(Dialog);

  open<C, D = unknown, R = unknown>(
    component: Type<C>,
    config: KoDialogConfig<D> = {},
  ): DialogRef<R, C> {
    const ref = this.dialog.open<R, D, C>(component, {
      data: config.data,
      ariaLabel: config.ariaLabel,
      disableClose: config.disableClose,
      role: "dialog",
      ariaModal: true,
      ...KO_DIALOG_SIZE,
      panelClass: [...KO_DIALOG_PANEL_CLASS, "p-5"],
      backdropClass: KO_DIALOG_BACKDROP_CLASS,
    });
    animateExit(ref, "dialog");
    return ref;
  }
}

import type { DialogRef } from "@angular/cdk/dialog";

export type KoExitKind = "dialog" | "left" | "right";

/**
 * Exit classes per panel kind, mirroring the enter classes. The strings are literal so Tailwind
 * generates them. `fill-mode-forwards` keeps the panel hidden if the backdrop (150ms) or the
 * panel ends before the close lands. `duration-*` stays on the pane from the enter classes.
 */
export const KO_EXIT_PANEL: Record<KoExitKind, { classes: string[]; durationMs: number }> = {
  dialog: {
    classes: ["animate-out", "fade-out-0", "zoom-out-95", "fill-mode-forwards"],
    durationMs: 200,
  },
  left: { classes: ["animate-out", "slide-out-to-left", "fill-mode-forwards"], durationMs: 300 },
  right: { classes: ["animate-out", "slide-out-to-right", "fill-mode-forwards"], durationMs: 300 },
};

export const KO_EXIT_BACKDROP = ["animate-out", "fade-out-0", "fill-mode-forwards"];

/** Slack on top of the animation duration before the fallback closes the dialog anyway. */
export const KO_EXIT_MARGIN_MS = 50;

const ENTER_CLASS = /^(animate-in|fade-in|zoom-in|slide-in)/;

type MatchMedia = (query: string) => { matches: boolean };

/** True when the user asked for reduced motion; false where `matchMedia` is missing. */
export function prefersReducedMotion(
  matchMedia: MatchMedia | undefined = globalThis.matchMedia?.bind(globalThis),
): boolean {
  return matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
}

export interface KoExitController {
  /** True between a close request and the real close. */
  readonly closing: boolean;
  /** Abort a pending close and bring the panel back. Returns whether one was pending. */
  cancel(): boolean;
  /** Close at once, skipping the animation (for example when the host component is destroyed). */
  closeNow(): void;
}

/**
 * Makes `ref.close()` play an exit animation first. The CDK calls `close` for Escape, backdrop
 * clicks and `closeOnOverlayDetachments` too, so patching it on the instance covers every path.
 * The result is kept and passed to the real close, so `ref.closed` still emits it, after the
 * animation. A second `close` while one is pending is ignored (the first result wins).
 */
export function animateExit<R, C>(
  ref: DialogRef<R, C>,
  kind: KoExitKind,
  reducedMotion: () => boolean = prefersReducedMotion,
): KoExitController {
  const realClose = ref.close.bind(ref);
  const { classes, durationMs } = KO_EXIT_PANEL[kind];
  let stop: (() => void) | undefined;
  let restore: (() => void) | undefined;

  const settle = (): void => {
    stop?.();
    stop = restore = undefined;
  };

  ref.close = (...args: Parameters<typeof realClose>): void => {
    if (stop) return;
    const pane = ref.overlayRef.overlayElement;
    if (reducedMotion() || !pane?.isConnected) {
      realClose(...args);
      return;
    }
    const backdrop = ref.overlayRef.backdropElement;
    const removed = Array.from(pane.classList).filter((name) => ENTER_CLASS.test(name));
    pane.classList.remove(...removed);
    pane.classList.add(...classes);
    backdrop?.classList.remove(
      ...Array.from(backdrop.classList).filter((n) => ENTER_CLASS.test(n)),
    );
    backdrop?.classList.add(...KO_EXIT_BACKDROP);

    const finish = (): void => {
      settle();
      realClose(...args);
    };
    const onEnd = (event: AnimationEvent): void => {
      if (event.target === pane) finish();
    };
    const timer = setTimeout(finish, durationMs + KO_EXIT_MARGIN_MS);
    pane.addEventListener("animationend", onEnd);
    stop = () => {
      clearTimeout(timer);
      pane.removeEventListener("animationend", onEnd);
    };
    restore = () => {
      pane.classList.remove(...classes);
      pane.classList.add(...removed);
      backdrop?.classList.remove(...KO_EXIT_BACKDROP);
      backdrop?.classList.add("animate-in", "fade-in-0");
    };
  };

  return {
    get closing() {
      return stop !== undefined;
    },
    cancel() {
      if (!stop) return false;
      restore?.();
      settle();
      return true;
    },
    closeNow() {
      settle();
      realClose();
    },
  };
}

import { describe, expect, it } from "vitest";
import { KO_EXIT_BACKDROP, KO_EXIT_PANEL, prefersReducedMotion } from "@/ui/primitives/dialog-exit";

describe("KO_EXIT_PANEL", () => {
  it("fades and zooms a dialog out, matching the enter duration", () => {
    expect(KO_EXIT_PANEL.dialog.classes).toEqual(
      expect.arrayContaining(["animate-out", "fade-out-0", "zoom-out-95"]),
    );
    expect(KO_EXIT_PANEL.dialog.durationMs).toBe(200);
  });

  it("slides a sheet out towards its own side", () => {
    expect(KO_EXIT_PANEL.left.classes).toContain("slide-out-to-left");
    expect(KO_EXIT_PANEL.right.classes).toContain("slide-out-to-right");
    expect(KO_EXIT_PANEL.right.durationMs).toBe(300);
  });

  it("fades the backdrop out", () => {
    expect(KO_EXIT_BACKDROP).toEqual(expect.arrayContaining(["animate-out", "fade-out-0"]));
  });
});

describe("prefersReducedMotion", () => {
  it("reads the media query", () => {
    const query = (matches: boolean) => (q: string) => {
      expect(q).toBe("(prefers-reduced-motion: reduce)");
      return { matches };
    };
    expect(prefersReducedMotion(query(true))).toBe(true);
    expect(prefersReducedMotion(query(false))).toBe(false);
  });

  it("is false where matchMedia is missing", () => {
    expect(prefersReducedMotion(undefined)).toBe(false);
  });
});

/** Points the surrounding `role="dialog"` panel at this element, so the title names the dialog. */
export function linkToPanel(
  host: HTMLElement,
  attribute: "aria-labelledby" | "aria-describedby",
): void {
  const panel = host.closest('[role="dialog"]');
  if (panel && !panel.hasAttribute(attribute)) panel.setAttribute(attribute, host.id);
}

import { linkToPanel } from "@/ui/primitives/dialog-panel";

describe("linkToPanel", () => {
  const build = (panelAttrs = "") => {
    const root = document.createElement("div");
    root.innerHTML = `<div role="dialog" ${panelAttrs}><h2 id="title">Title</h2></div><p id="outside">x</p>`;
    return {
      panel: root.querySelector<HTMLElement>('[role="dialog"]')!,
      title: root.querySelector<HTMLElement>("#title")!,
      outside: root.querySelector<HTMLElement>("#outside")!,
    };
  };

  it("points the dialog panel at the element", () => {
    const { panel, title } = build();
    linkToPanel(title, "aria-labelledby");
    expect(panel.getAttribute("aria-labelledby")).toBe("title");
  });

  it("keeps an attribute the panel already has", () => {
    const { panel, title } = build('aria-labelledby="mine"');
    linkToPanel(title, "aria-labelledby");
    expect(panel.getAttribute("aria-labelledby")).toBe("mine");
  });

  it("does nothing outside a dialog", () => {
    const { outside } = build();
    expect(() => linkToPanel(outside, "aria-describedby")).not.toThrow();
  });
});
